import { useEffect, useRef, useState, useMemo, useCallback } from 'react';
import { Camera } from '@mediapipe/camera_utils';
import * as handpose from '@tensorflow-models/handpose';
import '@tensorflow/tfjs-backend-webgl';
import usePrevious from './UsePrevious';

const DEFAULT_FINGER = { left: -200, top: -200, zIndex: 0 };
const DEFAULT_FINGERS = {
    thumb: { ...DEFAULT_FINGER },
    pointer: { ...DEFAULT_FINGER },
    middle: { ...DEFAULT_FINGER },
    ring: { ...DEFAULT_FINGER },
    pinky: { ...DEFAULT_FINGER },
};

const returnLandmarks = (hand) => ({
    thumb: { left: hand[4][0], top: hand[4][1], zIndex: hand[4][2] },
    pointer: { left: hand[8][0], top: hand[8][1], zIndex: hand[8][2] },
    middle: { left: hand[12][0], top: hand[12][1], zIndex: hand[12][2] },
    ring: { left: hand[16][0], top: hand[16][1], zIndex: hand[16][2] },
    pinky: { left: hand[20][0], top: hand[20][1], zIndex: hand[20][2] },
});

const CameraCanvas = ({ pressButton, APP_WRAPPER }) => {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const canvasContainer = useRef(null);
    const flashTimeoutRef = useRef(null);
    const lastLogTimeRef = useRef(0);

    const [handData, setHandData] = useState(null);
    const [cameraLoaded, setCameraLoaded] = useState(false);
    const [loadedModel, setLoadedModel] = useState(null);
    const [clickFlash, setClickFlash] = useState(false);

    const prevHandData = usePrevious(handData);

    // FIX: Move model loading into useEffect instead of during render
    useEffect(() => {
        let cancelled = false;
        const loadModel = async () => {
            try {
                const model = await handpose.load();
                if (!cancelled) {
                    setLoadedModel(model);
                }
            } catch (e) {
                console.error('Failed to load handpose model:', e);
            }
        };
        loadModel();
        return () => { cancelled = true; };
    }, []);

    // FIX: Memoize dimension ratios instead of recomputing every render
    const { WIDTH_RATIO, HEIGHT_RATIO } = useMemo(() => {
        const appWidth = APP_WRAPPER?.current?.offsetWidth || 620;
        const appHeight = APP_WRAPPER?.current?.offsetHeight || 360;
        return {
            WIDTH_RATIO: appWidth / 620,
            HEIGHT_RATIO: appHeight / 360,
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [APP_WRAPPER?.current?.offsetWidth, APP_WRAPPER?.current?.offsetHeight]);

    // Camera setup & cleanup
    useEffect(() => {
        const video = videoRef.current;
        if (!video) return;

        const camera = new Camera(video);
        camera.start();

        return () => {
            // FIX: Stop existing stream tracks directly — don't create a new getUserMedia stream
            const stream = video.srcObject;
            if (stream) {
                stream.getTracks().forEach((track) => track.stop());
            }
            camera.stop();
        };
    }, []);

    // Resize canvas to match container via ResizeObserver
    useEffect(() => {
        const canvas = canvasRef.current;
        const container = canvasContainer.current;
        if (!canvas || !container) return;

        const resizeObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                const { width, height } = entry.contentRect;
                canvas.width = width;
                canvas.height = height;
            }
        });
        resizeObserver.observe(container);
        return () => resizeObserver.disconnect();
    }, []);

    const fingerPos = useMemo(() => {
        if (handData?.landmarks) {
            return returnLandmarks(handData.landmarks);
        }
        return DEFAULT_FINGERS;
    }, [handData]);

    const prevFingerPos = useMemo(() => {
        if (prevHandData?.landmarks) {
            return returnLandmarks(prevHandData.landmarks);
        }
        // FIX: was `handData?.landmarks > 0` (array > number bug)
        if (handData?.landmarks?.length > 0) {
            return returnLandmarks(handData.landmarks);
        }
        return DEFAULT_FINGERS;
    }, [handData, prevHandData]);

    // FIX: Clean up flash timeout on unmount and before re-trigger
    const makeFlash = useCallback(() => {
        if (flashTimeoutRef.current) {
            clearTimeout(flashTimeoutRef.current);
        }
        setClickFlash(true);
        flashTimeoutRef.current = setTimeout(() => {
            setClickFlash(false);
            flashTimeoutRef.current = null;
        }, 500);
    }, []);

    // Cleanup flash timeout on unmount
    useEffect(() => {
        return () => {
            if (flashTimeoutRef.current) {
                clearTimeout(flashTimeoutRef.current);
            }
        };
    }, []);

    // Process finger data — compute click strength once, not per-finger
    useEffect(() => {
        let firstFinger = null;
        let pinching = false;
        let proximityCount = 1;
        let count = 0;
        let maxStrength = 0;
        let thumbData = null;
        let pointerData = null;
        let thumbPos = null;
        let pointerPos = null;

        const entries = Object.entries(fingerPos);

        for (const [key, value] of entries) {
            const left = value.left;
            const top = value.top;
            const zIndex = value.zIndex;
            const prevZ = prevFingerPos[key]?.zIndex || 0;
            const sensitivity = 10.5;
            const clicking = zIndex < prevZ - sensitivity;
            const currentStrength = prevZ - zIndex;
            const X_PIXELS = (620 - left) * WIDTH_RATIO;
            const Y_PIXELS = top * HEIGHT_RATIO;

            // FIX: Track max strength, only call setState once after the loop
            if (currentStrength > maxStrength) {
                maxStrength = currentStrength;
            }

            if (key === "pointer") {
                pointerPos = { left, top };
                pointerData = { left, top, clicking };
            }

            if (key === "thumb") {
                thumbPos = { left, top };
                thumbData = { left, top };
            }

            if (count === 0) {
                firstFinger = { firstLeft: left, firstTop: top };
                count++;
            }

            if (
                firstFinger &&
                Math.abs(firstFinger.firstLeft - left) < 50 &&
                Math.abs(firstFinger.firstTop - top) < 50
            ) {
                proximityCount++;
            }
        }

        // Check for pinch gesture: thumb and pointer should be close together
        // Skip pinch detection for off-screen/default positions
        let pinchDistance = null;
        const isOnScreen = thumbPos && pointerPos &&
            thumbPos.left > -100 && thumbPos.top > -100 &&
            pointerPos.left > -100 && pointerPos.top > -100;

        if (isOnScreen) {
            pinchDistance = Math.sqrt(
                Math.pow(thumbPos.left - pointerPos.left, 2) + 
                Math.pow(thumbPos.top - pointerPos.top, 2)
            );
            // Pinch detected if thumb and pointer are within 80 pixels of each other
            pinching = pinchDistance < 80;
        }

        // Call pressButton with the correct pinching state (only when on-screen)
        if (isOnScreen && pointerPos) {
            const X_PIXELS = (620 - pointerPos.left) * WIDTH_RATIO;
            const Y_PIXELS = pointerPos.top * HEIGHT_RATIO;
            const clicking = pointerData?.clicking || false;
            pressButton(X_PIXELS, Y_PIXELS, clicking, pinching);
            if (pointerData) {
                pointerData.pinching = pinching;
            }
        }

        // Minimal logging for thumb & pointer positions + pinch state (throttled to once per second)
        const now = Date.now();
        if (now - lastLogTimeRef.current >= 1000) {
            if (thumbData) {
                console.log(`[thumb] x:${thumbData.left.toFixed(0)} y:${thumbData.top.toFixed(0)}`);
            }
            if (pointerData) {
                const distanceInfo = pinchDistance !== null ? ` | distance:${pinchDistance.toFixed(0)}px` : '';
                console.log(`[pointer] x:${pointerData.left.toFixed(0)} y:${pointerData.top.toFixed(0)} | pinching:${pinching} | clicking:${pointerData.clicking}${distanceInfo}`);
            }
            lastLogTimeRef.current = now;
        }

        // FIX: Single state update instead of one per finger
        if (maxStrength > 10) {
            makeFlash();
        }
    }, [HEIGHT_RATIO, WIDTH_RATIO, fingerPos, pressButton, prevFingerPos, makeFlash]);

    // Draw finger indicator on canvas instead of using a CSS-positioned div
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Clear entire canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const pointerLeft = fingerPos.pointer.left;
        const pointerTop = fingerPos.pointer.top;

        // Don't draw if off-screen (default -200)
        if (pointerLeft < -100 || pointerTop < -100) return;

        const x = (620 - pointerLeft) * WIDTH_RATIO;
        const y = pointerTop * HEIGHT_RATIO;
        const radius = 14;

        ctx.save();

        // Outer glow
        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.shadowBlur = clickFlash ? 18 : 12;
        ctx.shadowColor = clickFlash
            ? 'rgba(123, 1, 238, 0.7)'
            : 'rgba(95, 188, 251, 0.95)';
        ctx.fillStyle = 'rgba(80, 79, 79, 0.47)';
        ctx.fill();

        // Inner bright ring
        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.lineWidth = 2;
        ctx.strokeStyle = clickFlash
            ? 'rgba(123, 1, 238, 0.8)'
            : 'rgba(95, 188, 251, 0.9)';
        ctx.shadowBlur = clickFlash ? 22 : 14;
        ctx.shadowColor = clickFlash
            ? 'rgb(95, 188, 251)'
            : 'rgba(95, 188, 251, 0.98)';
        ctx.stroke();

        ctx.restore();
    }, [fingerPos, clickFlash, WIDTH_RATIO, HEIGHT_RATIO]);

    // Hand detection loop
    useEffect(() => {
        const video = videoRef.current;
        let rafId = null;

        async function detectHands() {
            if (!loadedModel || !video) {
                rafId = requestAnimationFrame(detectHands);
                return;
            }

            try {
                const hands = await loadedModel.estimateHands(video);

                if (!cameraLoaded && hands) {
                    setCameraLoaded(true);
                }

                setHandData(hands[0] || null);
            } catch (e) {
                console.error('Hand detection error:', e);
            }

            rafId = requestAnimationFrame(detectHands);
        }

        detectHands();

        return () => {
            if (rafId) {
                cancelAnimationFrame(rafId);
            }
        };
    }, [loadedModel, cameraLoaded]);

    return (
        <div className="cameraCanvas" ref={canvasContainer}>
            {!cameraLoaded && (
                <div className="loadingScreen">CAMERA LOADING</div>
            )}
            <video ref={videoRef} className="input_video" id="video"></video>
            <canvas ref={canvasRef} className="output_canvas"></canvas>
            {/* Finger indicator is now drawn on the canvas above via 2D context */}
        </div>
    );
};

export default CameraCanvas;
